diff --git a/src/main/java/com/fasterxml/jackson/databind/deser/impl/CreatorCollector.java b/src/main/java/com/fasterxml/jackson/databind/deser/impl/CreatorCollector.java
index 8e38f5dec..4e476a001 100644
--- a/src/main/java/com/fasterxml/jackson/databind/deser/impl/CreatorCollector.java
+++ b/src/main/java/com/fasterxml/jackson/databind/deser/impl/CreatorCollector.java
@@ -282,7 +282,41 @@ public class CreatorCollector
                 }
             }
         }
-        return creator.getParameterType(ix);
+        JavaType paramType = creator.getParameterType(ix);
+        JavaType beanType = _beanDesc.getType();
+        System.err.println("DEBUG CreatorCollector: paramType=" + paramType + " beanType=" + beanType);
+        // [databind#1215]: Resolve type variables using the bean's type bindings.
+        // Need to resolve constructor parameter types like V[] where V is a type variable
+        // that should be bound based on the type arguments of the beanType.
+        if (beanType.getBindings().isEmpty()) {
+            // No type bindings, can't resolve
+            return paramType;
+        }
+
+        JavaType resolved;
+        if (paramType.isArrayType()) {
+            // For array types, resolve the component type and reconstruct
+            JavaType componentType = paramType.getContentType();
+            JavaType resolvedComponent = beanType.getTypeHandler() != null ?
+                componentType : componentType;
+
+            // Try to resolve using findSuperType to get the correct type bindings
+            JavaType creatorClass = _beanDesc.getTypeFactory().constructType(creator.getDeclaringClass());
+            JavaType superType = beanType.findSuperType(creator.getDeclaringClass());
+            if (superType != null && !superType.getBindings().isEmpty()) {
+                // Found the proper super type with bindings, try to resolve
+                resolvedComponent = superType.containedTypeOrUnknown(ix);
+                if (resolvedComponent != null && resolvedComponent != componentType) {
+                    resolved = _beanDesc.getTypeFactory().constructArrayType(resolvedComponent);
+                    System.err.println("DEBUG CreatorCollector: resolved array component from superType=" + resolved);
+                    return resolved;
+                }
+            }
+        }
+
+        resolved = _beanDesc.resolveType(paramType);
+        System.err.println("DEBUG CreatorCollector: resolved=" + resolved);
+        return resolved;
     }

     private <T extends AnnotatedMember> T _fixAccess(T member)
